import json,csv,hashlib
from pathlib import Path
scope={}
initial=json.loads(Path('initializations.json').read_text())
for series, vecs in initial.items():
 for label,vec in zip(('far','near'),vecs): scope[f'{series}/{label}']=(series,vec)
idx=json.loads(Path('bundle_index.json').read_text())
runs=json.loads(Path('run_records.json').read_text())
datahash={hashlib.sha256(p.read_bytes()).hexdigest():p.stem for p in Path('data').glob('*.csv')}
covered=set()
for r in runs:
 b=idx.get(r.get('loaded_bundle'),{})
 series=datahash.get(b.get('input_sha256'))
 vec=b.get('parameters')
 for uid,(s,v) in scope.items():
  if series==s and vec==v and r.get('solver')=='LM' and r.get('terminal') in ('converged','iteration-limit'):
   covered.add(uid)
missing=sorted(set(scope)-covered)
ans={'release':not missing,'scheduled_units':len(scope),'covered_units':len(covered),'outstanding':missing}
Path('answer.json').write_text(json.dumps(ans,separators=(',',':'))+'\n')
print(Path('answer.json').read_text())

