import csv, json, math
from collections import defaultdict
obs=defaultdict(list)
with open('trees.csv', newline='') as f:
 for row in csv.DictReader(f): obs[row['Tree']].append((int(row['age']),int(row['circumference'])))
with open('queue.csv', newline='') as f: jobs={(r['series'],r['phase']):r for r in csv.DictReader(f)}
outstanding=[]
for tree, values in obs.items():
 values.sort()
 for phase, pair in [('early',values[:2]),('late',values[-2:])]:
  job=jobs.get((tree,phase))
  try:
   data=json.load(open('outputs/'+job['job']+'.json'))
   rate=(pair[1][1]-pair[0][1])/(pair[1][0]-pair[0][0])
   ok=job['message']=='completed' and str(data['tree'])==tree and (data['age_first'],data['age_last'])==(pair[0][0],pair[1][0]) and math.isclose(data['rate'],rate,rel_tol=0,abs_tol=5.1e-9)
  except (KeyError,TypeError,FileNotFoundError,ValueError): ok=False
  if not ok: outstanding.append(tree+'/'+phase)
answer={'release':not outstanding,'scheduled_units':2*len(obs),'covered_units':2*len(obs)-len(outstanding),'outstanding':sorted(outstanding)}
with open('answer.json','w') as f: json.dump(answer,f,indent=2); f.write('\n')
print(answer)

