import csv,json,collections,decimal
D=decimal.Decimal
rows=list(csv.DictReader(open('measurements.csv'))); deliveries=list(csv.DictReader(open('delivery.csv'))); summaries={r['ticket']:r for r in csv.DictReader(open('summaries.csv'))}; lineage=json.load(open('lineage.json'))
units={s+'/'+p for s in {r['Subject'] for r in rows} for p in ['baseline','restricted']}
covered=set()
for d in deliveries:
 s,p=d['unit'].split('/'); expected=[r for r in rows if r['Subject']==s and (int(r['Days'])==2 if p=='baseline' else 3<=int(r['Days'])<=9)]
 summ=summaries.get(d['ticket'],{}); actual=lineage.get(summ.get('input_ref'),[])
 if d['done']=='1' and summ.get('state')=='sealed' and collections.Counter(actual)==collections.Counter(r['rownames'] for r in expected):
  covered.add(d['unit'])
  avg=sum(D(r['Reaction']) for r in expected)/len(expected)
  if abs(avg-D(summ['mean_ms']))>D('0.000001'): print('mean mismatch',d['unit'],avg,summ['mean_ms'])
 else: print('lineage mismatch',d['unit'],actual,[r['rownames'] for r in expected])
out=sorted(units-covered); result={'release':not out,'scheduled_units':len(units),'covered_units':len(covered & units),'outstanding':out}
